    {"id": "c_derleme_zinciri", "lang": "c", "course": "c", "title": "Derleme zinciri: merhaba.c adım adım (gcc -E / -S / -c)", "source": "Hafta03 s.16–24, s.35",
     "code": '/* merhaba.c — derleme zincirini adım adım izle (Linux terminali):\n *\n *   wc -l merhaba.c                 # 5-7 satır\n *   gcc -E merhaba.c -o merhaba.i   # 1) ön işleme (cpp)  -> ~800 satır!\n *   gcc -S merhaba.i -o merhaba.s   # 2) derleme  (cc1)   -> assembly\n *   head merhaba.s                  #    \'call puts@PLT\' göreceksin\n *   gcc -c merhaba.s -o merhaba.o   # 3) assembly (as)    -> obje dosyası\n *   file merhaba.o                  #    ELF 64-bit LSB relocatable\n *   nm merhaba.o                    #    U puts  /  T main\n *   gcc merhaba.o -o merhaba        # 4) bağlama  (ld)    -> çalıştırılabilir\n *   file merhaba                    #    ELF 64-bit LSB executable\n *   ldd merhaba                     #    libc.so.6 ...\n *   ./merhaba                       #    çalıştır\n *   strace ./merhaba 2>&1 | head    #    sistem çağrılarını izle\n *\n * Tek adımda: gcc merhaba.c -o merhaba\n */\n#include <stdio.h>\n\nint main() {\n    printf("Merhaba!\\n");\n    return 0;\n}\n'},
    {"id": "c_assembly_karsilik", "lang": "c", "course": "c", "title": "C satırları ve assembly karşılıkları (x = x + 3)", "source": "Hafta03 s.18–19",
     "code": '#include <stdio.h>\n\n/* gcc -S ile üretilen assembly (x86-64, AT&T sözdizimi):\n *\n *   int x = 5;      ->  movl $5, -4(%rbp)        # x = 5 (stack\'teki yerel değişken)\n *   x = x + 3;      ->  movl -4(%rbp), %eax      # eax = x\n *                       addl $3, %eax            # eax += 3\n *                       movl %eax, -4(%rbp)      # x = eax\n *\n * printf("Merhaba!\\n") ise assembly\'de \'call puts@PLT\' olur:\n * sabit metin + \'\\n\' -> derleyici daha basit olan puts\'u seçer.\n */\nint main() {\n    int x = 5;\n    x = x + 3;\n    printf("x = %d\\n", x);\n    printf("Merhaba!\\n");\n    return 0;\n}\n'},
    {"id": "c_write_syscall", "lang": "c", "course": "c", "title": "printf vs write(): sistem çağrısını doğrudan kullanmak", "source": "Hafta03 s.10–12, s.28",
     "code": '#include <stdio.h>\n#include <string.h>\n#include <unistd.h>   // write() — POSIX sistem çağrısı sarmalayıcısı\n\n/* printf -> libc (tampon + biçimlendirme) -> write syscall -> kernel -> ekran\n * write(fd, veri, bayt_sayisi): fd 1 = stdout, 2 = stderr\n * \'strace ./program\' ile iki yolun da write(1, ...) ürettiğini görebilirsin. */\nint main() {\n    printf("1) printf ile yazıldı\\n");\n    fflush(stdout);   // libc tamponunu boşalt: sıranın karışmaması için\n\n    const char *mesaj = "2) write ile doğrudan yazıldı\\n";\n    ssize_t n = write(1, mesaj, strlen(mesaj));\n\n    printf("write\'ın döndürdüğü değer: %zd bayt\\n", n);\n    fflush(stdout);   // yine boşalt: yoksa aşağıdaki "Mer" bu satırdan ÖNCE görünebilir\n    write(1, "Merhaba\\n", 3);   // sadece ilk 3 bayt: "Mer"\n    write(1, "\\n", 1);\n    return 0;\n}\n'},
    {"id": "c_elf_bolumler", "lang": "c", "course": "c", "title": "ELF bölümleri: .text / .data / .bss / sembol tablosu", "source": "Hafta03 s.21, s.25–26",
     "code": '#include <stdio.h>\n\nint sayac = 5;          // başlatılmış global    -> .data\nint toplam;             // başlatılmamış global  -> .bss (0 ile başlar)\nstatic int gizli = 7;   // static global         -> .data (nm\'de \'d\': yerel sembol)\n\nvoid yardimci(void) {   // fonksiyon kodu        -> .text (nm\'de \'T\')\n    toplam += sayac;\n}\n\n/* Derle ve incele:\n *   gcc -c elf.c -o elf.o && nm elf.o\n *     D sayac     (.data)\n *     B toplam    (.bss)\n *     d gizli\n *     T main / T yardimci\n *     U printf    (tanımsız: libc\'den bağlanacak)\n *   gcc elf.c -o elf && file elf && ldd elf\n */\nint main() {\n    yardimci();\n    yardimci();\n    printf("sayac=%d toplam=%d gizli=%d\\n", sayac, toplam, gizli);\n    return 0;\n}\n'},
    {"id": "c_linker_hata", "lang": "c", "course": "c", "title": "⚠️ Hatalı kod: undefined reference (linker hatasını oku)", "source": "Hafta03 s.23, s.37",
     "code": '#include <stdio.h>\n\n/* Prototip var, TANIM yok.\n * Derleyici (cc1) prototipi görüp geçer; bağlayıcı (ld) topla\'yı hiçbir obje\n * dosyasında bulamaz:\n *   undefined reference to `topla\'\n * Çözüm: fonksiyonu tanımla ya da tanımın olduğu dosyayı/kütüphaneyi ekle\n * (örn. pthread fonksiyonları için -pthread). */\nint topla(int a, int b);\n\nint main() {\n    printf("%d\\n", topla(2, 3));\n    return 0;\n}\n\n/* Düzeltilmiş hâli için şu tanımı ekle:\nint topla(int a, int b) {\n    return a + b;\n}\n*/\n'},
    # ───────────────────────── C · Hafta 4 (Process) ─────────────────────────
    {"id": "c_fork_basit", "lang": "c", "course": "c", "title": "fork(): 'fork'tan sonra' neden iki kez yazılır?", "source": "Process.pdf s.9",
     "code": '#include <stdio.h>\n#include <unistd.h>\n#include <sys/types.h>\n\nint main() {\n    printf("fork\'tan önce\\n");\n    fflush(stdout);          // tampon kopyalanmasın (çıktı dosyaya/boruya giderse önemli)\n    pid_t pid = fork();      // buradan sonra İKİ process var: parent + child\n    printf("fork\'tan sonra\\n");\n    return 0;\n}\n'},
    {"id": "c_fork_pid", "lang": "c", "course": "c", "title": "fork dönüş değeri: parent ve child PID karşılaştırma", "source": "Process.pdf s.11–12",
     "code": '#include <stdio.h>\n#include <unistd.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n\nint main() {\n    pid_t pid;\n    pid = fork();\n    if (pid < 0) {               // hata: -1\n        printf("fork başarısız!\\n");\n        return 1;\n    }\n    else if (pid == 0) {         // child: fork 0 döndürür\n        printf("CHILD: PID=%d, Parent=%d\\n", getpid(), getppid());\n    }\n    else {                       // parent: fork child\'ın PID\'ini döndürür\n        wait(NULL);              // (slaytta yok) çıktı sırası karışmasın diye\n        printf("PARENT: PID=%d, Child=%d\\n", getpid(), pid);\n    }\n    return 0;\n}\n'},
    {"id": "c_fork_bellek", "lang": "c", "course": "c", "title": "fork sonrası bellek izolasyonu (x = 100 / 200)", "source": "Process.pdf s.13–14",
     "code": '#include <stdio.h>\n#include <unistd.h>\n\nint main() {\n    int x = 100;\n    printf("fork öncesi: x=%d\\n", x);\n    fflush(stdout);\n    pid_t pid = fork();\n    if (pid == 0) {\n        // Child: kendi KOPYASINI değiştirir\n        x = 200;\n        printf("CHILD: x=%d (PID=%d)\\n", x, getpid());\n    } else {\n        // Parent: child\'ın değişikliği burayı etkilemez\n        sleep(1);\n        printf("PARENT: x=%d (PID=%d)\\n", x, getpid());\n    }\n    return 0;\n}\n'},
    {"id": "c_wait", "lang": "c", "course": "c", "title": "wait(): child'ı bekle ve çıkış kodunu al (42)", "source": "Process.pdf s.16–18",
     "code": '#include <stdio.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\nint main() {\n    pid_t pid = fork();\n    if (pid == 0) {\n        printf("CHILD: 2 saniye çalışacağım\\n");\n        sleep(2);\n        printf("CHILD: bittim\\n");\n        return 42;                       // çıkış kodu\n    } else {\n        int status;\n        printf("PARENT: child\'ı bekliyorum...\\n");\n        fflush(stdout);\n        wait(&status);                   // child bitene kadar BLOKE\n        if (WIFEXITED(status)) {\n            printf("PARENT: child %d ile bitti\\n", WEXITSTATUS(status));\n        }\n    }\n    return 0;\n}\n'},
    {"id": "c_exec", "lang": "c", "course": "c", "title": "exec(): process'in programını değiştirme (execl /bin/ls)", "source": "Process.pdf s.20–22",
     "code": '#include <stdio.h>\n#include <unistd.h>\n\nint main() {\n    printf("exec öncesi\\n");\n    fflush(stdout);\n    execl("/bin/ls", "ls", "-l", NULL);   // başarılıysa BURADAN GERİ DÖNMEZ\n    // Buraya sadece exec başarısız olursa gelinir\n    printf("exec başarısız!\\n");\n    return 1;\n}\n'},
    {"id": "c_fork_exec_wait", "lang": "c", "course": "c", "title": "fork + exec + wait: klasik shell modeli", "source": "Process.pdf s.23–24",
     "code": '#include <stdio.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\nint main() {\n    pid_t pid = fork();\n    if (pid == 0) {\n        // Child: ls -l çalıştır\n        execl("/bin/ls", "ls", "-l", NULL);\n        perror("exec başarısız");\n        return 1;\n    } else {\n        // Parent: bekle\n        int status;\n        wait(&status);\n        printf("\\nKomut bitti, çıkış kodu: %d\\n", WEXITSTATUS(status));\n    }\n    return 0;\n}\n'},
    {"id": "c_fork_sayma", "lang": "c", "course": "c", "title": "Kod okuma: kaç A, kaç B, kaç C? (fork sayma)", "source": "Process.pdf s.28–29",
     "code": '#include <stdio.h>\n#include <unistd.h>\n#include <sys/wait.h>\n\n/* Cevap: 1 A, 2 B, 4 C. Her fork process sayısını ikiye katlar (n fork -> 2^n process).\n * for (int i = 0; i < 3; i++) fork();  -> 2^3 = 8 process.\n * fflush olmadan çıktı boruya/dosyaya giderse printf tamponu da kopyalanır\n * ve A birden çok kez görünebilir. */\nint main() {\n    setvbuf(stdout, NULL, _IONBF, 0);   // tamponsuz çıktı\n    printf("A\\n");\n    fork();\n    printf("B\\n");\n    fork();\n    printf("C\\n");\n    while (wait(NULL) > 0) ;            // çocukları topla (zombi kalmasın)\n    return 0;\n}\n'},
    {"id": "c_taban_donusum", "lang": "c", "course": "donanim", "title": "Sayı sistemi dönüştürücü (BTP239 alıştırmaları için)", "source": "btp239_h1_donusumler.pdf", "stdin": "37",
     "code": '#include <stdio.h>\n\n/* Onluk bir sayıyı 2, 8 ve 16 tabanına çevirir.\n   Bölme yöntemi: kalanlar aşağıdan yukarı okunur (ilk kalan LSB). */\nvoid yazdir(int n, int taban) {\n    char basamak[] = "0123456789ABCDEF";\n    char sonuc[40];\n    int k = 0;\n    if (n == 0) { printf("0"); return; }\n    while (n > 0) {\n        sonuc[k++] = basamak[n % taban];\n        n /= taban;\n    }\n    while (k > 0) putchar(sonuc[--k]);\n}\n\nint main() {\n    int n;\n    printf("Onluk sayı: ");\n    scanf("%d", &n);\n    printf("\\n(%d)10 = (", n); yazdir(n, 2);  printf(")2\\n");\n    printf("(%d)10 = (", n);   yazdir(n, 8);  printf(")8\\n");\n    printf("(%d)10 = (", n);   yazdir(n, 16); printf(")16\\n");\n    return 0;\n}\n'},
    {"id": "c_watt_hesabi", "lang": "c", "course": "donanim", "title": "Güç kaynağı watt hesabı + rack-mount U yüksekliği", "source": "BTP239_Hafta02 s.23, s.31–32",
     "code": '#include <stdio.h>\n\n/* BTP239 Hafta 2: tipik güç gereksinimleri tablosunun ÜST değerleriyle sistem watt hesabı.\n   Sıradan kullanıcıya en az 400-500 W PSU önerilir (ilaveler için pay bırak). */\nint main() {\n    const char *parca[] = {"Anakart", "Dual Core işlemci", "RAM", "HDD (7200 rpm)", "CD-ROM", "Ethernet kartı", "PCI kart"};\n    int watt[]          = {30,        100,                 30,    15,               25,       4,                5};\n    int adet = sizeof(watt) / sizeof(watt[0]);\n    int toplam = 0;\n\n    for (int i = 0; i < adet; i++) {\n        printf("%4d W  %s\\n", watt[i], parca[i]);\n        toplam += watt[i];\n    }\n    printf("-------------\\n");\n    printf("%4d W  Toplam\\n", toplam);\n    printf("%4d W  %%30 pay ile -> en az 400-500 W PSU seç\\n", toplam * 13 / 10);\n\n    /* Rack-mount: 1U = 1,75 inç, genişlik her zaman 19 inç (48,3 cm) */\n    for (int u = 1; u <= 4; u++)\n        printf("%dU kasa = %.2f inç yükseklik\\n", u, u * 1.75);\n    return 0;\n}\n'},
    {"id": "c_bant_genisligi", "lang": "c", "course": "donanim", "title": "Veri yolu bant genişliği: AGP çarpanı ve PCIe hat sayısı", "source": "BTP239_Hafta03 s.18–19",
     "code": '#include <stdio.h>\n\n/* AGP: paralel, 32 bit; her çarpan 266 MB/s  (1x, 2x, 4x, 8x)\n   PCIe: seri; her hat tek yön için 250 MB/s (x1, x4, x8, x16) -> x16 = 4 GB/s */\nint main() {\n    int agp[] = {1, 2, 4, 8};\n    for (int i = 0; i < 4; i++)\n        printf("AGP %dx  = %4d MB/s\\n", agp[i], agp[i] * 266);\n\n    int hat[] = {1, 4, 8, 16};\n    for (int i = 0; i < 4; i++)\n        printf("PCIe x%-2d = %4d MB/s (tek yön)\\n", hat[i], hat[i] * 250);\n    return 0;\n}\n'},
    {"id": "c_subnet_hesap", "lang": "c", "course": "ag", "title": "Subnet hesaplayıcı (AND işlemi ile ağ/broadcast)", "source": "hafta_5_ipv4_ipv6_ve_subnetting.pdf", "stdin": "192 168 1 130 26",
     "code": '#include <stdio.h>\n\n/* Girdi: IP\'nin 4 okteti ve prefix (örn: 192 168 1 130 26)\n   Ağ adresi = IP AND mask, Broadcast = ağ OR (ters mask) */\nvoid ip_yaz(unsigned int ip) {\n    printf("%u.%u.%u.%u", (ip >> 24) & 255, (ip >> 16) & 255, (ip >> 8) & 255, ip & 255);\n}\n\nint main() {\n    unsigned int a, b, c, d, prefix;\n    scanf("%u %u %u %u %u", &a, &b, &c, &d, &prefix);\n    unsigned int ip = (a << 24) | (b << 16) | (c << 8) | d;\n    unsigned int mask = prefix == 0 ? 0 : 0xFFFFFFFFu << (32 - prefix);\n    unsigned int ag = ip & mask;\n    unsigned int bc = ag | ~mask;\n    unsigned int host_bit = 32 - prefix;\n\n    printf("IP        : "); ip_yaz(ip);   printf(" /%u\\n", prefix);\n    printf("Mask      : "); ip_yaz(mask); printf("\\n");\n    printf("Ağ adresi : "); ip_yaz(ag);   printf("\\n");\n    printf("Broadcast : "); ip_yaz(bc);   printf("\\n");\n    if (host_bit >= 2) {\n        printf("İlk host  : "); ip_yaz(ag + 1); printf("\\n");\n        printf("Son host  : "); ip_yaz(bc - 1); printf("\\n");\n        printf("Kullanılabilir host: 2^%u - 2 = %u\\n", host_bit, (1u << host_bit) - 2);\n    }\n    return 0;\n}\n'},
    {"id": "c_arp_hedefi", "lang": "c", "course": "ag", "title": "Yerel mi uzak mı? ARP kimin MAC'ini sorar (AND kararı)", "source": "hafta_7_arp_ve_routing.pdf s.5", "stdin": "192.168.1.10 24 192.168.1.1 8.8.8.8",
     "code": '#include <stdio.h>\n\n/* Girdi: kaynak IP, prefix, default gateway, hedef IP\n   örn: 192.168.1.10 24 192.168.1.1 8.8.8.8\n   Kaynak cihaz hedef IP\'yi kendi maskesiyle AND\'ler:\n     aynı ağ  -> ARP doğrudan HEDEF için, hedef MAC = alıcı cihaz\n     uzak ağ  -> ARP GATEWAY (router LAN arayüzü) için, hedef MAC = router,\n                 hedef IP değişmez! */\nunsigned int oku(void) {\n    unsigned int a, b, c, d;\n    scanf("%u.%u.%u.%u", &a, &b, &c, &d);\n    return (a << 24) | (b << 16) | (c << 8) | d;\n}\n\nvoid yaz(unsigned int ip) {\n    printf("%u.%u.%u.%u", (ip >> 24) & 255, (ip >> 16) & 255, (ip >> 8) & 255, ip & 255);\n}\n\nint main() {\n    unsigned int kaynak = oku();\n    unsigned int prefix;\n    scanf("%u", &prefix);\n    unsigned int gw = oku();\n    unsigned int hedef = oku();\n    unsigned int mask = prefix == 0 ? 0 : 0xFFFFFFFFu << (32 - prefix);\n\n    printf("Kaynak ağı : "); yaz(kaynak & mask); printf("/%u\\n", prefix);\n    printf("Hedef ağı  : "); yaz(hedef & mask);  printf("/%u\\n", prefix);\n\n    if ((kaynak & mask) == (hedef & mask)) {\n        printf("YEREL ağ -> ARP isteği hedef için: "); yaz(hedef); printf("\\n");\n        printf("Çerçeve: hedef MAC = alıcı cihazın MAC\'i, iletişim switch üzerinden\\n");\n    } else {\n        printf("UZAK ağ  -> ARP isteği gateway için: "); yaz(gw); printf("\\n");\n        printf("Çerçeve: hedef MAC = router MAC, hedef IP = "); yaz(hedef); printf(" (değişmez)\\n");\n    }\n    return 0;\n}\n'},
    {"id": "c_longest_prefix", "lang": "c", "course": "ag", "title": "Router rota arama: Longest Prefix Match + TTL", "source": "hafta_7_arp_ve_routing.pdf s.6–7", "stdin": "10.1.5.20 64",
     "code": '#include <stdio.h>\n\n/* Basit bir routing table: hedef IP\'ye uyan EN UZUN prefix\'li rota seçilir.\n   Hiçbiri uymazsa S* 0.0.0.0/0 (Gateway of Last Resort) zaten her şeye uyar.\n   Router önce TTL\'yi 1 azaltır; 0 olursa paketi düşürür.\n   Girdi: hedef IP ve TTL  (örn: 10.1.5.20 64) */\nstruct Rota {\n    const char *kod;\n    unsigned int ag;\n    unsigned int prefix;\n    const char *cikis;\n};\n\nunsigned int ip(unsigned int a, unsigned int b, unsigned int c, unsigned int d) {\n    return (a << 24) | (b << 16) | (c << 8) | d;\n}\n\nint main() {\n    struct Rota tablo[] = {\n        {"C ", ip(192, 168, 10, 0), 24, "g0/0/0 (doğrudan bağlı)"},\n        {"S ", ip(10, 1, 0, 0),     16, "next-hop 10.0.0.2"},\n        {"S ", ip(10, 1, 5, 0),     24, "next-hop 10.0.0.6"},\n        {"S*", ip(0, 0, 0, 0),       0, "next-hop 203.0.113.1 (varsayılan)"},\n    };\n    int n = sizeof(tablo) / sizeof(tablo[0]);\n\n    unsigned int a, b, c, d;\n    int ttl;\n    scanf("%u.%u.%u.%u %d", &a, &b, &c, &d, &ttl);\n    unsigned int hedef = ip(a, b, c, d);\n\n    ttl--;\n    if (ttl <= 0) {\n        printf("TTL 0 oldu -> paket düşürüldü\\n");\n        return 0;\n    }\n\n    int en_iyi = -1;\n    for (int i = 0; i < n; i++) {\n        unsigned int mask = tablo[i].prefix == 0 ? 0 : 0xFFFFFFFFu << (32 - tablo[i].prefix);\n        int uyar = (hedef & mask) == tablo[i].ag;\n        printf("%s %u.%u.%u.%u/%-2u  %s\\n", tablo[i].kod, tablo[i].ag >> 24, (tablo[i].ag >> 16) & 255,\n               (tablo[i].ag >> 8) & 255, tablo[i].ag & 255, tablo[i].prefix, uyar ? "uyuyor" : "-");\n        if (uyar && (en_iyi < 0 || tablo[i].prefix > tablo[en_iyi].prefix))\n            en_iyi = i;\n    }\n    printf("Seçilen rota: /%u -> %s, yeni TTL = %d\\n", tablo[en_iyi].prefix, tablo[en_iyi].cikis, ttl);\n    return 0;\n}\n'},
