    {"id": "cs_kek_tarifi", "lang": "csharp", "course": "cs", "title": "Kek tarifindeki değişkenler", "source": "Degiskenler_.pptx slayt 5, 11",
     "code": 'using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int yumurtaSayisi = 3;\n        double sekerBardagi = 1.5;\n        int pisirmeSuresi = 35;\n        string kekCesidi = "Kakaolu";\n        bool firinIsindi = false;\n\n        Console.WriteLine(kekCesidi + " kek: " + yumurtaSayisi + " yumurta, " + sekerBardagi + " bardak şeker");\n\n        // Tarifi iki katına çıkar\n        yumurtaSayisi = yumurtaSayisi * 2;\n        sekerBardagi = sekerBardagi * 2;\n        Console.WriteLine("Yeni yumurta sayısı: " + yumurtaSayisi);\n        Console.WriteLine("Yeni şeker miktarı: " + sekerBardagi + " bardak");\n        Console.WriteLine("Pişirme süresi (değişmedi): " + pisirmeSuresi + " dk, fırın ısındı mı? " + firinIsindi);\n    }\n}\n'},
